INSERT INTO "comments" ("id","discussion_id","author_id","content","parent_comment_id","is_anonymous","upvote_count","downvote_count","created_at","updated_at","deleted_at") VALUES
('3a881cc9-7062-4f21-892a-2615e209862a','b336609d-b0ca-4e45-8b57-6018d01ac913','67ec271a-777b-4818-871a-6edbe517c499','Mình cũng đang học phần Lập lịch CPU. Quantum nhỏ giúp phản hồi nhanh nhưng tăng số lần chuyển ngữ cảnh. Khi so sánh cần đo cả thời gian chờ, turnaround và chi phí chuyển ngữ cảnh trên cùng workload. Bạn có thể chia sẻ ví dụ đầu vào hoặc các bước đã thử để nhóm đối chiếu không?',NULL,TRUE,0,1,'2026-09-28T15:22:14.362Z','2026-09-28T15:22:14.362Z',NULL),
